const form = $('Add A Vendor To Watch').first().json;
const name = String(form.vendor_name || '').trim();
const url = String(form.list_url || '').trim();
const problems = [];
if (name.length < 2) problems.push('the vendor name is too short');
// the page address is checked here rather than trusted: a value that is not a web address would make
// every later run fail to fetch, and the run would then have to be reported as unreachable for ever
if (!/^https?:\/\/[^\s]+\.[^\s]{2,}/i.test(url)) problems.push('the list page must be a full web address beginning with http or https');
const countries = String(form.approved_countries || '').split(/[,;|]/).map(s => s.trim()).filter(Boolean);
return [{ json: {
  vendor_name: name, list_url: url, owner_team: String(form.owner_team || '').trim(),
  approved_countries: countries.join(', '), contract_ref: String(form.contract_ref || '').trim(),
  enabled: problems.length === 0, added_at: new Date().toISOString(),
  notes: problems.length ? 'not enabled: ' + problems.join('; ') : 'added by form; the first check captures the baseline',
  accepted: problems.length === 0, problems: problems.join('; ')
} }];

const policy = $('Set Watch Policy').first().json;
const all = $input.all().map(i => i.json).filter(v => v && v.vendor_name);
const isOn = v => v.enabled === true || String(v.enabled).toLowerCase() === 'true';
const ready = all.filter(v => isOn(v) && String(v.list_url || '').trim());
const defaults = String(policy.default_approved_countries || '').split(/[,;|]/).map(s => s.trim()).filter(Boolean);
// One header item, so the register below is read once rather than once per vendor.
return [{ json: {
  run_id: String($execution.id), started_at: new Date().toISOString(),
  vendors_total: all.length, vendors_ready: ready.length,
  min_entries: Number(policy.min_entries_to_trust) || 3,
  shrink_ratio: Number(policy.suspect_shrink_ratio) || 0.5,
  max_entries: Number(policy.max_entries_per_page) || 300,
  country_words: String(policy.country_words || ''),
  vendors: ready.map(v => ({
    vendor_name: v.vendor_name, list_url: String(v.list_url).trim(), owner_team: v.owner_team || '',
    approved_countries: String(v.approved_countries || '').trim() || defaults.join(', '),
    contract_ref: v.contract_ref || ''
  }))
} }];

const head = $('Select The Vendors').first().json;
// The register is read once, before the loop, so the comparison downstream can take the pages from the
// loop's own output instead of having them overwritten by a table read.
const known = {};
for (const it of $input.all()) {
  const r = it.json;
  if (r && r.vendor_name && r.entry_text) known[r.vendor_name] = (known[r.vendor_name] || 0) + 1;
}
if (!head.vendors.length) {
  return [{ json: { skip: true, vendor_name: '', run_id: head.run_id, started_at: head.started_at,
    vendors_ready: 0, no_vendor_reason: head.vendors_total
      ? 'no vendor is both enabled and has a list page'
      : 'the sub_vendors table is empty; add one with the form' } }];
}
return head.vendors.map(v => ({ json: {
  ...v, skip: false,
  run_id: head.run_id, started_at: head.started_at, vendors_ready: head.vendors_ready,
  min_entries: head.min_entries, shrink_ratio: head.shrink_ratio, max_entries: head.max_entries,
  country_words: head.country_words, known_entries: known[v.vendor_name] || 0
} }));

// Reduce a fetched page to a set of candidate entry lines and a hash. No HTML parsing beyond stripping
// tags: the comparison downstream is a line-level set difference, which survives a page redesign far
// better than trying to understand a table.
let vendor = {};
try { vendor = $('Loop Over Vendors').first().json || {}; } catch (e) { vendor = {}; }
const res = $input.first().json || {};
const err = res.error ? String(res.error.message || res.error) : '';
let body = '';
if (typeof res.data === 'string') body = res.data;
else if (typeof res.body === 'string') body = res.body;
else if (typeof res === 'string') body = res;
else body = String(res.data || res.body || '');

const maxEntries = Number(vendor.max_entries) || 300;
const countryWords = String(vendor.country_words || '').split(/[,;|]/).map(s => s.trim()).filter(Boolean);

let status = 'ok';
if (err) status = 'unreachable';
else if (!body || body.length < 40) status = 'unreachable';

let entries = [];
let hash = '';
if (status === 'ok') {
  const text = body
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<\/(tr|li|p|div|h[1-6]|table)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&#\d+;/g, ' ');
  const seen = new Set();
  for (const rawLine of text.split('\n')) {
    const line = rawLine.replace(/\s+/g, ' ').trim();
    if (line.length < 3 || line.length > 160) continue;
    if (!/[A-Za-z]/.test(line)) continue;
    const low = line.toLowerCase();
    // page furniture that appears on every site and would otherwise churn the diff every run
    if (/^(home|menu|search|cookie|privacy policy|terms|contact|sign in|log in|subscribe|accept|back to top|skip to)\b/.test(low)) continue;
    if (seen.has(low)) continue;
    seen.add(low);
    const country = countryWords.find(c => new RegExp('\\b' + c.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i').test(line)) || '';
    entries.push({ entry_text: line, country });
    if (entries.length >= maxEntries) break;
  }
  // a cheap stable hash so an unchanged page is visibly unchanged without storing the page
  let h = 0;
  const joined = entries.map(e => e.entry_text).join('\n');
  for (let i = 0; i < joined.length; i++) { h = ((h << 5) - h + joined.charCodeAt(i)) | 0; }
  hash = 'h' + (h >>> 0).toString(36) + '-' + entries.length;
}
return [{ json: {
  vendor_name: vendor.vendor_name || '', list_url: vendor.list_url || '',
  approved_countries: vendor.approved_countries || '', owner_team: vendor.owner_team || '',
  run_id: vendor.run_id || '', started_at: vendor.started_at || '',
  min_entries: vendor.min_entries, shrink_ratio: vendor.shrink_ratio,
  status, fetch_error: err.slice(0, 200), entries, entry_count: entries.length,
  content_hash: hash, page_chars: body.length
} }];

const pages = $input.all().map(i => i.json).filter(p => p && p.vendor_name && p.skip !== true);
const skipped = $input.all().map(i => i.json).find(p => p && p.skip === true);
const register = {};
for (const it of $('Read The Register').all()) {
  const r = it.json;
  if (!r || !r.vendor_name || !r.entry_text) continue;
  (register[r.vendor_name] = register[r.vendor_name] || []).push(r);
}
const norm = s => String(s).toLowerCase().replace(/\s+/g, ' ').trim();
const findings = [];
const registerWrites = [];
const now = new Date().toISOString();
let fetched = 0, unreachable = 0, suspect = 0, added = 0, removed = 0, countryAlerts = 0;

for (const p of pages) {
  const known = register[p.vendor_name] || [];
  const knownSet = new Set(known.map(r => norm(r.entry_text)));
  const approved = String(p.approved_countries || '').split(/[,;|]/).map(s => s.trim()).filter(Boolean);
  const baseline = known.length === 0;

  if (p.status === 'unreachable') {
    unreachable += 1;
    findings.push({ vendor_name: p.vendor_name, change_type: 'unreachable', severity: 'high',
      entry_text: '', country: '', source: 'rules',
      detail: 'the page could not be read, so nothing can be said about this vendor this run: ' + (p.fetch_error || 'empty response') });
    continue;                                   // never touch the register on a failed fetch
  }
  fetched += 1;

  // a page that suddenly holds almost nothing is a redesign, a login wall or a blocked request.
  // Applying its removals would quietly empty the register, so removals are held back and flagged.
  const shrank = !baseline && p.entry_count < Math.max(Number(p.min_entries) || 3, Math.floor(known.length * (Number(p.shrink_ratio) || 0.5)));
  if (shrank) {
    suspect += 1;
    findings.push({ vendor_name: p.vendor_name, change_type: 'suspect_shrink', severity: 'high',
      entry_text: '', country: '', source: 'rules',
      detail: 'the page returned ' + p.entry_count + ' entries where the register holds ' + known.length +
              '; removals were not applied and a person should open the page' });
  }

  for (const e of p.entries) {
    const key = norm(e.entry_text);
    const isNew = !knownSet.has(key);
    if (isNew && !baseline) {
      added += 1;
      findings.push({ vendor_name: p.vendor_name, change_type: 'added', severity: 'medium',
        entry_text: e.entry_text, country: e.country, source: 'rules',
        detail: 'this line was not on the page at the last check' });
      if (e.country && approved.length && !approved.some(c => norm(c) === norm(e.country))) {
        countryAlerts += 1;
        findings.push({ vendor_name: p.vendor_name, change_type: 'country_not_approved', severity: 'critical',
          entry_text: e.entry_text, country: e.country, source: 'rules',
          detail: 'the line names ' + e.country + ', which is not in the approved list for this vendor (' + approved.join(', ') + ')' });
      }
    }
    registerWrites.push({ entry_key: p.vendor_name + '::' + key.slice(0, 120), vendor_name: p.vendor_name,
      entry_text: e.entry_text, country: e.country,
      status: baseline ? 'baseline' : (isNew ? 'added' : 'present'),
      first_seen: isNew ? now : (known.find(r => norm(r.entry_text) === key) || {}).first_seen || now,
      last_seen: now, run_id: p.run_id });
  }

  if (!shrank && !baseline) {
    const seenNow = new Set(p.entries.map(e => norm(e.entry_text)));
    for (const r of known) {
      if (seenNow.has(norm(r.entry_text))) continue;
      removed += 1;
      findings.push({ vendor_name: p.vendor_name, change_type: 'removed', severity: 'medium',
        entry_text: r.entry_text, country: r.country || '', source: 'rules',
        detail: 'this line was on the page at the last check and is gone now' });
      registerWrites.push({ entry_key: r.entry_key, vendor_name: r.vendor_name, entry_text: r.entry_text,
        country: r.country || '', status: 'removed', first_seen: r.first_seen || now, last_seen: now, run_id: p.run_id });
    }
  }
  if (baseline) {
    findings.push({ vendor_name: p.vendor_name, change_type: 'baseline', severity: 'low',
      entry_text: '', country: '', source: 'rules',
      detail: p.entry_count + ' entries recorded as the starting point; the next check compares against them' });
  }
}

const head = pages[0] || skipped || {};
const addedLines = findings.filter(f => f.change_type === 'added').slice(0, 20);
const reviewPrompt = addedLines.length
  ? 'LINES THAT APPEARED ON A VENDOR SUB-PROCESSOR PAGE SINCE THE LAST CHECK.\n\n'
    + addedLines.map(f => f.vendor_name + ' | ' + f.entry_text).join('\n')
    + '\n\nFor each line, say the company name it appears to name and the country it appears to say, copying both from the line itself. '
    + 'If a line names no company, or no country is written in it, leave that field empty. Never guess a country that is not written in the line.'
  : 'No lines appeared. Return an empty list.';

return [{ json: {
  run_id: head.run_id || String($execution.id), started_at: head.started_at || now,
  vendors_checked: pages.length, vendors_fetched: fetched, vendors_unreachable: unreachable,
  vendors_suspect: suspect, added_count: added, removed_count: removed, country_alerts: countryAlerts,
  findings, register_writes: registerWrites, added_lines: addedLines, review_prompt: reviewPrompt,
  no_vendor_reason: (skipped && skipped.no_vendor_reason) || ''
} }];

const s = $('Compare With The Register').first().json;
const out = ($input.first().json || {}).output;
const parsed = out && typeof out === 'object' ? out : null;
let reviewerStatus = 'not_answered';
const enriched = [], rejected = [];
const findings = s.findings.map(f => ({ ...f }));
if (parsed && Array.isArray(parsed.entries)) {
  reviewerStatus = 'answered';
  for (const e of parsed.entries) {
    const line = String((e && e.entry_text) || '').trim();
    const company = String((e && e.company) || '').trim();
    const country = String((e && e.country) || '').trim();
    const target = findings.find(f => f.change_type === 'added' && f.entry_text === line);
    // the model may only describe a line that is really in the run, and may only name a country that is
    // really written in that line. It never creates, removes or re-grades a finding.
    if (!target) { rejected.push('line not in this run'); continue; }
    if (country && !new RegExp(country.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i').test(line)) {
      rejected.push(target.vendor_name + ': country not written in the line'); continue;
    }
    if (company) target.detail = target.detail + ' (reads as: ' + company + (country ? ', ' + country : '') + ')';
    if (country && !target.country) target.country = country;
    enriched.push(line);
  }
}

let verdict, reason;
if (!s.vendors_checked) { verdict = 'INCOMPLETE'; reason = s.no_vendor_reason || 'no vendor was ready to check; add one with the form and give it a list page'; }
else if (s.vendors_unreachable) { verdict = 'INCOMPLETE'; reason = s.vendors_unreachable + ' vendor page(s) could not be read, so this run cannot say they are unchanged'; }
else if (s.vendors_suspect) { verdict = 'INCOMPLETE'; reason = s.vendors_suspect + ' page(s) shrank enough to look broken; removals were held back'; }
else if (s.country_alerts) { verdict = 'ALERT'; reason = s.country_alerts + ' new line(s) name a country that is not approved'; }
else if (s.added_count || s.removed_count) { verdict = 'CHANGED'; reason = s.added_count + ' line(s) appeared and ' + s.removed_count + ' disappeared'; }
else { verdict = 'UNCHANGED'; reason = 'every page read the same as last time'; }

const byVendor = {};
for (const f of findings) { if (f.change_type !== 'baseline') (byVendor[f.vendor_name] = byVendor[f.vendor_name] || []).push(f); }
const report = [
  'Run ' + s.run_id + ': ' + verdict + '. ' + reason + '.',
  s.vendors_checked + ' vendor(s) checked, ' + s.vendors_fetched + ' read, ' + s.vendors_unreachable
    + ' unreachable, ' + s.vendors_suspect + ' suspect.',
  Object.keys(byVendor).length
    ? Object.entries(byVendor).map(([v, fs]) => '  ' + v + ': ' + fs.slice(0, 8).map(f => f.change_type + (f.entry_text ? ' "' + f.entry_text.slice(0, 70) + '"' : '')).join('; ')).join('\n')
    : '',
  rejected.length ? 'Reviewer suggestions discarded: ' + rejected.length : ''
].filter(Boolean).join('\n');

return [{ json: {
  run_id: s.run_id, started_at: s.started_at, vendors_checked: s.vendors_checked,
  vendors_fetched: s.vendors_fetched, vendors_unreachable: s.vendors_unreachable,
  vendors_suspect: s.vendors_suspect, added_count: s.added_count, removed_count: s.removed_count,
  country_alerts: s.country_alerts, verdict, reason, reviewer_status: reviewerStatus,
  reviewer_enriched: enriched.length, report, findings, register_writes: s.register_writes
} }];

const s = $('Combine Into A Verdict').first().json;
const now = new Date().toISOString();
if (!s.findings.length) {
  return [{ json: { run_id: s.run_id, vendor_name: 'none', change_type: 'none', severity: 'low',
    entry_text: '', country: '', detail: s.reason, source: 'rules', found_at: now } }];
}
return s.findings.map(f => ({ json: {
  run_id: s.run_id, vendor_name: f.vendor_name, change_type: f.change_type, severity: f.severity,
  entry_text: String(f.entry_text || '').slice(0, 400), country: f.country || '',
  detail: String(f.detail || '').slice(0, 800), source: f.source || 'rules', found_at: now } }));

// One row per entry per vendor. Nothing is written for a vendor whose page could not be read, so an
// outage leaves the register exactly as it was rather than emptying it.
const s = $('Combine Into A Verdict').first().json;
if (!s.register_writes.length) {
  return [{ json: { entry_key: 'none::none', vendor_name: 'none', entry_text: '', country: '',
    status: 'none', first_seen: s.started_at, last_seen: s.started_at, run_id: s.run_id } }];
}
return s.register_writes.map(r => ({ json: r }));
